"""Ordered chains: one red and N skipped, not N reds (plan D5).

The Stage-1 matrices are chains. A case captures an id, the next one edits that record, the one
after re-reads it — so when step 2 fails, steps 3 to 9 fail too, for a reason that has nothing to
do with what they test. A 44-case matrix then reports 8 failures where one thing is wrong, and the
triage cost of that is the whole reason a human stops reading the output.

pytest has no built-in for this and `pytest-dependency` is not a dependency of this repo, so it is
two hooks over a stash on the class collector. The logic lives here rather than in `conftest.py`
because a conftest is not importable: a rule about which failures break a chain is worth a test of
its own, and this is the shape that can have one without Docker.

**Any** phase counts, not only `call`. A setup failure means the substrate was never built; a
teardown failure means it was left in a state nobody described. Either way the next step is
reading something other than what it was promised, and reporting that as a second defect is the
noise this exists to remove.
"""

from __future__ import annotations

import pytest

# Set on the *class* collector, so a chain is scoped to its class exactly like `seeded_tree` is.
# A module-level stash would let one broken chain skip an unrelated one in the same file.
BROKEN = pytest.StashKey[str]()


def note_outcome(stash: pytest.Stash, *, name: str, when: str, failed: bool) -> None:
    """Record the **first** failure in this chain, and only the first.

    The later ones are consequences; naming a consequence in the skip message sends the reader
    to the wrong test. `when` is carried into the message because "failed in teardown" and
    "failed in call" send them to different places.
    """
    if not failed or BROKEN in stash:
        return
    stash[BROKEN] = name if when == "call" else f"{name} ({when})"


def skip_reason(stash: pytest.Stash) -> str | None:
    """Why this step is not being run, or `None` if the chain is still intact."""
    broken = stash.get(BROKEN, None)
    return f"earlier step in this chain failed: {broken}" if broken else None
